import os
import json
import re
from typing import Dict, Any, Optional
from src.layer2_diagnostician.agent import DiagnosticReport
from src.utils.logger import logger

BASE_PARSER_TEMPLATE = '''# Auto-Generated Self-Healing Data Pipeline Parser
# Generated by Layer 3 Patch Generator Agent

def parse_payload(payload: dict) -> dict:
    """
    Parses and normalizes incoming weather payload.
    Applies alias mappings, type conversions, missing defaults, and outlier clipping.
    """
    parsed = {}
    
__ALIAS_LOGIC__

__TYPE_AND_DEFAULT_LOGIC__

__OUTLIER_LOGIC__

__DEDUP_LOGIC__

    return parsed
'''

class PatchGenerator:
    """Layer 3: Code Patch Generation Agent for Data Ingestion Pipeline."""

    def __init__(self, api_key: Optional[str] = None):
        self.api_key = api_key or os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")

    def generate_patch(self, diagnostic: DiagnosticReport, feedback_context: str = "") -> str:
        """Generates executable Python parser patch code based on diagnosis."""

        cat = diagnostic.anomaly_category
        field = diagnostic.affected_field
        replacement_key = diagnostic.found_replacement_key

        alias_logic = "    # Default field extraction\n"
        type_default_logic = "    # Type enforcement & fallback defaults\n"
        outlier_logic = "    # Outlier handling\n"
        dedup_logic = "    # Deduplication check\n"

        # Schema drift / Renamed field patch
        if cat == "schema_drift" and replacement_key:
            alias_logic += f"    # Field rename patch: map '{replacement_key}' -> '{field}'\n"
            alias_logic += f"    if '{field}' not in payload and '{replacement_key}' in payload:\n"
            alias_logic += f"        payload['{field}'] = payload.pop('{replacement_key}')\n"

        # General extraction for expected fields
        expected_fields = [
            "latitude", "longitude", "temperature_2m",
            "relative_humidity_2m", "precipitation",
            "surface_pressure", "wind_speed_10m", "time"
        ]

        for f in expected_fields:
            if f == field and cat == "type_mismatch":
                type_default_logic += f"""    # Type mismatch fix for field '{f}'
    val = payload.get('{f}')
    if val is not None:
        try:
            parsed['{f}'] = float(val) if not isinstance(val, bool) else 0.0
        except (ValueError, TypeError):
            parsed['{f}'] = 0.0
    else:
        parsed['{f}'] = 0.0
"""
            elif f == field and cat == "null_field":
                type_default_logic += f"""    # Null/missing fallback for field '{f}'
    val = payload.get('{f}')
    if val is None or val == "":
        parsed['{f}'] = 0.0  # Safe default coalescing
    else:
        try:
            parsed['{f}'] = float(val)
        except (ValueError, TypeError):
            parsed['{f}'] = 0.0
"""
            else:
                type_default_logic += f"""    val = payload.get('{f}')
    if val is None:
        parsed['{f}'] = 0.0 if '{f}' != 'time' else "1970-01-01T00:00:00"
    elif '{f}' == 'time':
        parsed['{f}'] = str(val)
    else:
        try:
            parsed['{f}'] = float(val) if not isinstance(val, bool) else 0.0
        except (ValueError, TypeError):
            parsed['{f}'] = 0.0
"""

        # Outlier clipping
        if cat == "outlier":
            outlier_logic += f"""    # Outlier clipping patch for field '{field}'
    if '{field}' in parsed:
        if parsed['{field}'] > 100.0 or parsed['{field}'] < -60.0:
            parsed['{field}'] = 20.0  # Clip or replace extreme anomaly
"""

        # Deduplication
        if cat == "duplicate_record":
            dedup_logic += """    # Drop duplicate record indicators
    if '_is_duplicate_flag' in payload:
        parsed['_is_duplicate'] = True
"""

        code = BASE_PARSER_TEMPLATE.replace("__ALIAS_LOGIC__", alias_logic)\
                                  .replace("__TYPE_AND_DEFAULT_LOGIC__", type_default_logic)\
                                  .replace("__OUTLIER_LOGIC__", outlier_logic)\
                                  .replace("__DEDUP_LOGIC__", dedup_logic)

        return code
